#include "political_governance_agency_business.hpp"
#include "political_governance_agency_access.hpp"
namespace hanmo::resident {
Status validate_political_governance_agencies(const PoliticalGovernanceAgencyBusinessContext& x){if(!x.result_match)return common_failure("PoliticalGovernanceAgencyResultReadRequired");auto valid=validate_political_governance_agency_sources(x.rules);return valid.ok?validate_political_governance_agency_player_results(x.rules.common,x.rules.state,x.result_match):valid;}
Outcome<PoliticalGovernanceAgencyQuote> preview_political_governance_agency_business(const PoliticalGovernanceAgencyBusinessContext& x,const StableId& actor,const PoliticalGovernanceAgencyCommand& command){auto valid=validate_political_governance_agencies(x);if(!valid.ok)return {false,{},valid.error};auto quote=preview_political_governance_agency(x.rules,actor,command);if(!quote.ok)return quote;if(const auto* issue=std::get_if<PoliticalIssueAgencyGovernance>(&command)){const auto& r=x.rules;PoliticalGovernanceAgencyAccess access(r);auto source=access.agency_for_commission(issue->offer_fact_id,actor);if(!source.ok)return {false,{},source.error};const auto& a=source.value;PoliticalGovernanceCommissionCommand original{a.principal,issue->executor_actor_id,a.jurisdiction_id,a.commission_policy_id,a.public_inventory_id,a.jurisdiction_revision};valid=validate_public_relief_commission_plan(r.common,r.economy,x.relief_catalog,r.politics,r.governance_catalog,original);if(!valid.ok)return {false,{},valid.error};}return quote;}
Outcome<StableId> apply_political_governance_agency_business_in_candidate(CommonStore& common,PoliticsGovernanceState& governance,PoliticalGovernanceAgencyState& state,const PoliticalGovernanceAgencyBusinessContext& x,const StableId& actor,const PoliticalGovernanceAgencyCommand& command,const PoliticalGovernanceAgencyQuote& quote){auto prepared=preview_political_governance_agency_business(x,actor,command);if(!prepared.ok)return {false,{},prepared.error};if(&governance!=&x.rules.governance)return {false,{},common_failure("PoliticalGovernanceAgencyCandidateMismatch").error};if(const auto* issue=std::get_if<PoliticalIssueAgencyGovernance>(&command))return apply_political_governance_agency_issue_in_candidate(common,governance,state,x.rules,actor,*issue,quote);return apply_political_governance_agency_mandate_in_candidate(common,state,x.rules,actor,command,quote);}
}
